def attach_particle(word: str, particle: str) -> str:
    def has_batchim(char: str) -> bool:
        """Check if a Hangul character has a final consonant (batchim)"""
        if not char:
            return False
        code = ord(char)
        # Check if it's a Hangul syllable
        if 0xAC00 <= code <= 0xD7A3:
            # Extract jongseong (final consonant)
            jongseong = (code - 0xAC00) % 28
            return jongseong > 0
        return False

    def get_batchim_char(char: str) -> int:
        """Get the jongseong value (0 if no batchim)"""
        if not char:
            return 0
        code = ord(char)
        if 0xAC00 <= code <= 0xD7A3:
            return (code - 0xAC00) % 28
        return 0

    # Determine the last meaningful character
    last_char = word[-1]

    # Handle digits
    if last_char.isdigit():
        digit = int(last_char)
        # Sino-Korean digit pronunciations
        # For "으로/로": 1(일), 7(칠), 8(팔) have ㄹ batchim, others follow normal rules
        sino_korean = {
            '0': (False, False),  # 영 - vowel, no special ㄹ
            '1': (True, True),    # 일 - has ㄹ, special for 으로/로
            '2': (False, False),  # 이 - vowel
            '3': (True, False),   # 삼 - consonant ㅁ
            '4': (False, False),  # 사 - vowel
            '5': (False, False),  # 오 - vowel
            '6': (True, False),   # 육 - consonant ㄱ
            '7': (True, True),    # 칠 - has ㄹ, special for 으로/로
            '8': (True, True),    # 팔 - has ㄹ, special for 으로/로
            '9': (False, False),  # 구 - vowel
        }
        has_batchim_val, is_special_rieul = sino_korean[last_char]
    else:
        # Hangul syllable
        has_batchim_val = has_batchim(last_char)
        jongseong = get_batchim_char(last_char)
        # ㄹ is the 8th jongseong (index 8 in the jongseong list)
        is_special_rieul = (jongseong == 8)  # ㄹ batchim

    # Apply particle rules
    if particle == "은/는":
        return word + ("은" if has_batchim_val else "는")
    elif particle == "이/가":
        return word + ("이" if has_batchim_val else "가")
    elif particle == "을/를":
        return word + ("을" if has_batchim_val else "를")
    elif particle == "과/와":
        return word + ("과" if has_batchim_val else "와")
    elif particle == "으로/로":
        # Special case: ㄹ batchim becomes "로"
        if is_special_rieul:
            return word + "로"
        return word + ("으로" if has_batchim_val else "로")

    return word
